import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Loong: Generating Minute-level Long Videos with Autoregressive Language Models","description":"","frontmatter":{"title":"Loong: Generating Minute-level Long Videos with Autoregressive Language Models","arxiv":"2410.02757","date":"2024-10-03","authors":"Yuqing Wang, Tianwei Xiong, Daquan Zhou, Zhijie Lin, Yang Zhao, Bingyi Kang, Jiashi Feng, Xihui Liu","categories":"cs.CV","topics":"自回归视频生成, 分钟级长视频, 损失重加权","outline":[2,2]},"headers":[],"relativePath":"papers/2410.02757.md","filePath":"papers/2410.02757.md","lastUpdated":null}'),e={name:"papers/2410.02757.md"};function l(i,s,m,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="loong-generating-minute-level-long-videos-with-autoregressive-language-models" tabindex="-1">Loong: Generating Minute-level Long Videos with Autoregressive Language Models <a class="header-anchor" href="#loong-generating-minute-level-long-videos-with-autoregressive-language-models" aria-label="Permalink to &quot;Loong: Generating Minute-level Long Videos with Autoregressive Language Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2410.02757" target="_blank" rel="noreferrer">2410.02757</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-10-03（v2 修订于 2025-04-02）</td></tr><tr><td><strong>作者</strong></td><td>Yuqing Wang, Tianwei Xiong, Daquan Zhou, Zhijie Lin, Yang Zhao, Bingyi Kang, Jiashi Feng, Xihui Liu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把文本 token 与离散视频 token 拼成一条单向序列从零训 LLaMA 结构的解码器，用渐进短到长训练 + 早期帧损失加权解决长视频训练的损失失衡，再用「解码回像素再重新编码」消除因果 tokenizer 造成的续写分布漂移，从 10 秒外推到分钟级。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/autoregressive">自回归视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>2024 年前后的视频生成基本停在几秒钟。要讲一个有内容的故事，需要的是分钟级、且在这一分钟里允许场景切换与大幅运动的视频。扩散路线当时的长视频方案（Gen-L-Video 的重叠片段聚合、FreeNoise 的噪声重排、StreamingT2V 的记忆块）都是在短片段生成器外面套一层拼接逻辑，长程一致性靠工程手段维持。</p><p>自回归 LLM 在文本上早就证明了长序列建模能力，也能训练在短序列上再外推到更长。把这套能力直接搬到视频上看起来顺理成章，但当时最好的 LLM 路线视频生成器（VideoPoet）也只能生成 2 秒高质量片段并迭代延展到 10 秒。本文要回答的问题很直接：<strong>到底是什么在拦着自回归语言模型生成长视频</strong>。这个问题重要，因为如果障碍只是工程细节，那么视频生成就能直接继承 LLM 这十年积累的长上下文、scaling、多模态统一等全部红利。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>VideoPoet</strong> 是最接近的对照。它用预训练 T5 编码文本、对条件 token 用双向 attention、对视频 token 用因果 attention，能出 2 秒高质量片段并延展到 10 秒。这个设计的代价是它与 GPT 式的纯因果序列建模范式不一致，条件部分双向、生成部分单向的混合结构不便于把文本、视频、其他模态统一进同一条序列。</p><p><strong>Phenaki</strong> 用 masked video transformer 生成可变长视频，走的是并行解码而非严格 next-token，长程一致性依赖 mask 调度。</p><p><strong>LongVideoGAN / NUWA-XL / GAIA-1</strong> 分别用 GAN、diffusion-over-diffusion、世界模型做长视频，但都限定在特定域（人体、卡通、驾驶），开放域不适用。</p><p><strong>StreamingT2V</strong> 是当时最强的开源长视频基线，建立在 Stable Video Diffusion 上，用记忆块维持外观。它的问题与所有「短片段 + 拼接」方案相同：模型本身从未在长序列上学过依赖关系。</p><p>论文没有把这些方法批评成「思路错了」，而是指出一个更朴素的事实：LLM 路线之所以没人做长视频，是因为<strong>直接在长视频上训根本训不出来</strong>，而这个失败原因此前没有被诊断清楚。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是承认失败并去测量它。作者在 65 帧（10 秒，约 4356 token）视频上直接训练，然后按帧段画损失曲线，看到一个很干净的结构：第 1–17 帧的 token 损失明显高于第 18–65 帧，而第 50–65 帧的平均损失最小。这个现象有一个不需要新理论就能给出的解释——next-token prediction 训练时后面的帧能看到前面<strong>真值</strong>帧的 token，视频帧间冗余极大，于是预测后面帧几乎是抄写任务；预测第一帧却只能靠文本。</p><p>第二步是从这个观察推出后果。序列越长，容易 token 的数量增长越快，它们累加起来的损失压过少数难 token，梯度方向被简单任务主导，结果是早期帧质量崩坏——而早期帧崩了，整段视频就没救了。</p><p>第三步是想对策。既然问题是「难易 token 数量失衡」，就有两个正交的杠杆：让模型先在短序列上把难的部分学会（渐进短到长），以及在长序列阶段直接给难 token 加权（损失重加权）。</p><p>第四步是推理侧。训练只到 10 秒，要到 60 秒必须迭代续写。作者试了最自然的做法——直接拿上一段的 token 当条件——结果画质在训练长度之外急剧退化。诊断出来的原因是因果 tokenizer 的 token 错位：一段视频末尾 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 帧的 token 是在「前面所有帧都在」的上下文里编出来的，而新一段开头 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 帧的 token 在训练时是没有前文的，两者分布不同。于是解法就浮现了：把生成的 token 解码回像素，再重新编码一次，让条件 token 回到训练时的分布。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>长视频自回归训练的真正敌人是帧间冗余：它让后面的帧变成抄写题，海量简单 token 的损失淹没了少数真正困难的早期帧 token。先在短视频上把难题学会、再在长视频阶段给早期帧加权，就把梯度重新分配回该学的地方。推理侧的对应问题是因果 tokenizer 让「有前文的 token」和「无前文的 token」分布不同，把生成结果解码回像素再重编码一次即可把条件拉回训练分布。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>Tokenizer</strong>。复现 MAGVIT2 式的因果 3D CNN（单独处理首帧），空间下采样 8 倍、时间下采样 4 倍，总压缩率约 256；量化用 Clustering Vector Quantization（CVQ），比原始 VQ 的码本利用率更高，码本大小 8192，参数量 246M。一段 10 秒视频（65 帧，每帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span>）被压成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">17</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">16</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">16</span></span></span></span> 个离散 token。分辨率压到 128 是刻意的：用空间换时间跨度，高分辨率留给后处理。</p><p><strong>序列格式</strong>。文本 token 与视频 token 拼成统一序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord mathbf">s</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord mathbf">t</span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf" style="margin-right:0.016em;">v</span><span class="mclose">]</span></span></span></span>，全部使用因果 attention，不用预训练文本编码器。词表 = 32000 文本 + 8192 视频 + 10 特殊 token = 40202。</p><p><strong>主干</strong>。LLaMA 架构，700M / 3B / 7B 三档，<strong>从零训练</strong>，不加载任何文本预训练权重。</p><p><strong>三阶段训练</strong>。stage-1 在 100M 文本-图像对（从 CC12M 与 LAION-2B 过滤）上做文生图预训练 200k 步；stage-2 图像与 17 帧视频片段联合训练 200k 步，batch 512，视频数据来自 WebVid-10M 与从 HDVG 过滤的 5.5M 片段；stage-3 帧数提到 65（10 秒）继续联合训练 100k 步，batch 256，并在此阶段开启早期帧损失加权（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.0</span></span></span></span>）。三阶段都用 AdamW、基础学习率 1.0e-4、前 10000 步线性 warmup 后余弦退火。tokenizer 本身也按 1 → 17 → 65 帧渐进训练，分辨率固定 128，batch 64，400k 步。</p><p><strong>推理</strong>，走一遍完整例子：给定一条文本 prompt，模型先自回归生成 65 帧的视频 token（图 4 中的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">9</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）；取最后 5 帧解码回像素，再用 tokenizer 重新编码得到干净的条件 token（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">7</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">9</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）；把这些重编码 token 与文本 token 一起作为条件生成下一段（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">10</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">13</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）；重复直到目标长度。采样用 top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">50</span></span></span></span>；classifier-free guidance 比例 7.5。一分钟视频在这套设置下约 26112 个视频 token。最后用现成的超分与 refinement 模型做后处理，只提分辨率与细节，不改内容与运动。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>基础目标是视频 token 上的 next-token prediction 负对数似然</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">t</span><span class="mclose">)</span></span></span></span></span></p><p>这里的关键不在公式本身，而在于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 变大时各项的<strong>难度分布</strong>。因为相邻帧高度冗余，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 越靠后，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6079em;vertical-align:-0.1774em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span></span></span></span> 中可直接复制的信息越多，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">t</span><span class="mclose">)</span></span></span></span> 越小。总损失是这些项的和，于是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 从 17 帧涨到 65 帧时，新增的几乎全是小项，但它们的<strong>数量</strong>足以让梯度方向被它们支配。</p><p>损失重加权就是对这个求和做分段处理：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">weighted</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">−</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord mathnormal">λ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:3.181em;vertical-align:-1.3527em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8557em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3527em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">t</span><span class="mclose">)</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 是前 17 帧对应的 token 数，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>。这个式子朴素到几乎不像一个方法，但它正对着诊断出来的病因：既然早期 token 少而难，就把它们在梯度里的份额乘上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">λ</span><span class="mclose">)</span></span></span></span>。论文取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.0</span></span></span></span>，即早期帧权重翻倍。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>模型规模是否 scaling？</strong> 因为缺少通用的长视频 benchmark，作者自建了一个：从 WebVid 验证集取最长的 1000 段，各截成 27 秒（其中最短者的时长），指标用 FVD 与 CLIP(ViT-L/14) 算的 Video-Text Matching。在相同迭代数下，700M / 3B / 7B 的 FVD 为 633 / 572 / 432，VTM 为 21.5 / 22.8 / 24.1，两个指标都随规模单调改善。</p><p><strong>短视频上是否有竞争力？</strong> MSR-VTT 零样本、16 帧评测：Loong 的 FVD 是 274，仅次于 VideoPoet 的 213，好于 Show-1(538)、ModelScopeT2V(550)、MagicVideo(998)、CogVideo(1294)。CLIPSIM 方面 Loong 是 0.2903，低于 Show-1(0.3072) 与 VideoPoet(0.3049)。作者把 CLIPSIM 的劣势归因于从零训练、没有借用 T5 或 CLIP 的文本表示，这个解释合理但没有做消融验证。</p><p><strong>训练策略的两项设计有用吗？</strong> 这里的证据是定性的。图 5 对比直接长视频训练与渐进+加权训练在前 17 帧的生成结果，前者物体外观明显退化、结构信息大量丢失，后者保持完好。图 6 对比有无 token 重编码的续写，无重编码时续写段出现外观与内容的突变。这两项消融<strong>没有给出 FVD 或 VTM 数字</strong>，是本文实验部分最明显的缺口。</p><p><strong>采样策略。</strong> 贪心解码（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>）稳定但几乎静止，全词表多项式采样动态但质量差，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">50</span></span></span></span> 折中。作者明确写出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 越小运动越少。</p><p><strong>长视频上是否赢过基线？</strong> 用户研究：50 条 prompt 生成 1 分钟视频，与 StreamingT2V 双盲对比，收集 440 份回答，内容一致性胜率 0.83 对 0.125，图文匹配胜率 0.65 对 0.19。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：直接在 65 帧视频上做 next-token prediction 训练会失败，原因是帧间冗余让后段 token 变成抄写题，其累加损失压过少数困难的早期帧 token 并主导梯度。对策是把训练拆成图像 → 17 帧 → 65 帧三阶段，并在最后阶段给前 17 帧的 token 损失乘上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">λ</span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。推理侧的对应障碍是因果 tokenizer 使「带前文编码」与「无前文编码」的 token 分布不一致，解法是把生成结果解码回像素后重新编码再作为条件。整套系统在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span> 上运行、由 LLaMA 结构从零训练、词表 40202、tokenizer 压缩率约 256，最终从 10 秒外推到分钟级。模型规模从 700M 到 7B，自建 27 秒 benchmark 上 FVD 从 633 降到 432，MSR-VTT 短视频 FVD 274 仅次于 VideoPoet。</p><p><strong>3 句话版</strong>：长视频自回归训练的瓶颈是损失失衡而不是模型容量，渐进短到长加早期帧加权就能解决。续写时的画质崩坏源于因果 tokenizer 的分布错位，解码-重编码即可修复。两项修复合起来让一个从零训练的 LLaMA 式解码器生成出分钟级视频。</p><p><strong>1 句话版</strong>：把长视频训练的难点定位成 token 难度分布失衡，并用两个极简的修正（损失加权 + token 重编码）把纯自回归路线推到分钟级。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>用户研究里的「content consistency」能代表长视频质量</strong>。论文自己在采样策略一节写明，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 越小生成越稳定、运动越少，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 时视频几乎静止。这意味着「一致性」这个维度存在一个平凡解——少动就赢。而 Loong 的对照方 StreamingT2V 建立在 SVD 上，两个系统的运动幅度先验并不相同。0.83 对 0.125 的胜率因此无法区分「Loong 的长程建模更好」与「Loong 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">50</span></span></span></span> 下的运动幅度恰好更保守」。</p><p>论文为这条假设提供的证据是：图文匹配这一维 Loong 也赢（0.65 对 0.19），而静止视频通常拿不到高图文匹配。这个反驳有一定力量，但图文匹配由人评、prompt 只有 50 条、且两项评分来自同一批评测员的同一次对比，无法排除光环效应。真正缺的证据是一个<strong>运动幅度的客观测量</strong>（光流幅值、帧间差分能量之类）与一条平凡基线（把第一帧复制 60 秒）的得分。少了这两样，一致性优势的归因就是开放的。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周的版本不必复现 7B，也不必碰长视频训练。只验证论文的核心诊断：</p><ol><li>拿任意开源离散视频 tokenizer（或自己训一个小的因果 3D VAE），把一批 65 帧、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span> 的视频编码成 token。</li><li>训一个 300M 级别的因果 Transformer 做 next-token prediction，<strong>按帧段记录平均损失</strong>（帧 1、帧 2–17、帧 18–49、帧 50–65 分别统计）。若复现出「早期帧损失显著高于末段」的结构，第一条诊断成立。</li><li>同一份数据、同一算力预算下跑两组：直接 65 帧训练 vs 先 17 帧再 65 帧 + 早期帧加权 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。测两个量：前 17 帧的重建质量（对固定 prompt 生成后算 FVD 或 LPIPS），以及整段的 FVD。</li><li><strong>必须加的对照</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 但同样做渐进训练。论文把渐进训练与损失加权作为一个整体消融，没有拆开，所以「加权到底贡献了多少」目前是未知的。这一格恰好是最省事又最有信息量的实验。</li></ol><p>判据：若 (3) 中改进主要来自渐进训练而 (4) 显示 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span></span></span></span> 无差异，那么论文强调的损失重加权就是可有可无的，这个阴性结果本身值得报告。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对 token 重编码这一条设计攻击。论文对续写退化的诊断是「因果 tokenizer 造成条件 token 分布错位」，解法是解码后重编码。但同一现象还有一个更平凡的替代解释：<strong>重编码经过了一次有损的 decode-encode 往返，相当于对生成的 token 做了一次去噪投影</strong>，把累积的、离开真实 token 流形的误差拍回码本上的合法组合。若这个解释成立，那么重编码的收益与 tokenizer 的因果性无关，任何有损重量化都能达到同样效果。</p><p>具体反例实验：训练一个<strong>非因果</strong>（双向 3D 卷积、无因果 padding）的视频 tokenizer，其余设置照搬 Loong，再做续写。按论文的诊断，非因果 tokenizer 不存在「首 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 帧无前文」的问题，直接用上一段 token 续写应该不退化，重编码应当带来接近零的增益。若实测发现非因果 tokenizer 下重编码依然显著改善续写质量，那么原诊断被推翻，真正起作用的是量化投影而非分布对齐。</p><p>第二个可预测的失败条件：重编码只保留最后 5 帧作为条件，即条件窗口约 1.5 帧 token 深度。任何跨度超过这个窗口的语义（一个角色在第 10 秒出现、第 40 秒再出现）在结构上无法被传递。构造一批「实体反复出现」的 prompt（论文的 50 条 prompt 未针对这一点设计），Loong 应当可预测地失败，且失败与模型规模无关。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动这个想法的局限</strong>：Loong 的续写记忆是一个固定长度的像素窗口（最后 5 帧），信息量恒定且与内容无关。无论这 5 帧里是一段静止的天空还是一个刚出场的角色，传给下一段的 token 预算完全一样。这与文本 LLM 形成鲜明反差——文本的上下文里，一个专有名词只占几个 token 却能携带跨越万字的约束。</p><p><strong>新的 framing</strong>：把长视频自回归的上下文分成两条<strong>不同码率</strong>的通道，而不是一条统一的视频 token 流。低码率通道存「持久量」（实体身份、场景布局、光照方向），用极少的 token 表示、永不滑出窗口；高码率通道存「瞬时量」（当前运动状态），只保留最近若干帧并随时丢弃。这样长程一致性由低码率通道负责，而它的成本不随视频长度增长。</p><p><strong>可借鉴的相邻领域工具</strong>：视频编码里的 I 帧/P 帧与 GOP 结构，本质上就是按持久性分配码率；以及语音领域的 residual vector quantization，天然给出分层码率的 token 流。</p><p><strong>第一个实验</strong>：在 Loong 的 tokenizer 上加一路极窄的「场景码本」（比如每段视频 16 个 token，码本 1024），训练时用一个辅助目标强制它可预测同一视频后续片段的实体身份（用现成的检测/ReID 模型给伪标签）。推理时这 16 个 token 与文本 token 一起常驻上下文，永不被滑出。评测就用 §11 里那批「实体反复出现」的 prompt，测第 40 秒时角色与第 10 秒的身份相似度。若这条窄通道能在几乎不增加 token 预算的前提下显著提升跨段身份保持，就说明长视频的上下文应当按持久性分层，而不是按时间均匀截断。</p>',58)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
